/**
 * The page outside the shell: sign-in, sign-up, a setup step, a status (`design/archetypes/auth-page.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/auth-page.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { createMemo, mergeProps, type JSX } from 'solid-js'
import { Dynamic } from 'solid-js/web'

import {
  PageTransition,
  claimSlot,
  classes,
  createDerived,
  elementRef,
  resolveSlot,
  scope,
  watchEffect,
  type Defaults,
} from '@polymorph/solid'
import styles from '@polymorph/recipes/archetypes/auth-page.module.css'
import transitions from '@polymorph/recipes/conventions/page-transitions.module.css'
import Card from '../structure/Card'

export interface AuthPageProps {
  /**
   * An accessible back control, when this step has a return destination.
   */
  backAction?: JSX.Element
  /**
   * The product's wordmark, centred above the card.
   */
  brand?: JSX.Element
  /**
   * The line under the actions, inside the card (the login block's structure), such as "Don't
   * have an account? Sign up". It is inside the card, not under it, which is why it is a
   * separate slot. A sentence offering the other account action belongs to the form it is an
   * alternative to. Below the card it would float on the background, detached from the form.
   * `footer` keeps the outside position for page-level links.
   */
  cardFooter?: JSX.Element
  /**
   * FormFields and the submit Button. On a status page, the notice and the actions. Omitted when
   * the title and description say everything and the reader has nothing to do here.
   */
  children?: JSX.Element
  description?: JSX.Element
  /**
   * A row of Links below the card, such as legal, support or a locale switch.
   */
  footer?: JSX.Element
  illustration?: JSX.Element
  /**
   * The layout, where `illustrated` is the public account layout with host-supplied artwork.
   */
  layout?: 'centered' | 'illustrated'
  pending?: boolean
  /**
   * The `<h1>`.
   */
  title: string
  transitionKey?: string
}

/** The page outside the shell: sign-in, sign-up, a setup step, a status. */
export default function AuthPage(given: AuthPageProps): JSX.Element {
  const props = mergeProps(
    { layout: 'centered', pending: false } as Defaults<AuthPageProps, 'layout' | 'pending'>,
    claimSlot(given),
  )
  return scope(() => {
    const body = elementRef<HTMLElement>()
    const backActionSlot = resolveSlot(() => props.backAction)
    const brandSlot = resolveSlot(() => props.brand)
    const cardFooterSlot = resolveSlot(() => props.cardFooter)
    const descriptionSlot = resolveSlot(() => props.description)
    const footerSlot = resolveSlot(() => props.footer)
    const illustrationSlot = resolveSlot(() => props.illustration)
    const illustrated = createDerived(() => props.layout === 'illustrated')
    const effect1 = () => {
      void (
        illustrated.value &&
        body.value
          ?.querySelectorAll('[data-auth-enter]')
          .forEach((item, index) =>
            (item as HTMLElement).style.setProperty(
              '--pm-page-enter-order',
              String(Math.min(index, 9)),
            ),
          )
      )
    }
    watchEffect(
      createMemo(() => [illustrated.value, props.transitionKey]),
      effect1,
      true,
    )
    return (
      <main
        class={classes(styles.page, illustrated.value ? styles.illustrated : undefined)}
        aria-busy={props.pending ? true : undefined}
        data-auth-layout={props.layout}
        data-member="auth-page"
      >
        {illustrated.value && brandSlot.filled() ? (
          <div class={styles.topbar}>{brandSlot()}</div>
        ) : null}
        {/* body */}
        <div class={styles.body} ref={body.attach}>
          {/* column */}
          <Dynamic
            component={PageTransition}
            class={classes(
              styles.column,
              props.transitionKey !== undefined ? transitions.page : undefined,
            )}
            as="div"
            transitionKey={props.transitionKey}
            pending={props.pending}
            ribbon={transitions.indicator}
          >
            {illustrated.value && illustrationSlot.filled() ? (
              <div class={styles.illustration} aria-hidden="true">
                {illustrationSlot()}
              </div>
            ) : null}
            {/* formColumn */}
            <div class={styles.formColumn}>
              {!illustrated.value && brandSlot.filled() ? (
                <div class={styles.brand}>{brandSlot()}</div>
              ) : null}
              {illustrated.value ? (
                <div class={styles.frame}>
                  {/* card */}
                  <div class={styles.card}>
                    {/* heading */}
                    <div class={styles.heading} data-auth-enter={''}>
                      {/* titleRow */}
                      <div
                        class={classes(
                          styles.titleRow,
                          backActionSlot.filled() ? styles.withBack : undefined,
                        )}
                      >
                        {backActionSlot.filled() ? (
                          <div class={styles.backAction}>{backActionSlot()}</div>
                        ) : null}
                        {/* title */}
                        <h1 class={styles.title}>{props.title}</h1>
                      </div>
                      {descriptionSlot.filled() ? (
                        <p class={styles.description}>{descriptionSlot()}</p>
                      ) : null}
                    </div>
                    {props.children}
                    {cardFooterSlot.filled() ? (
                      <div class={styles.cardFooter}>{cardFooterSlot()}</div>
                    ) : null}
                  </div>
                </div>
              ) : (
                <Card>
                  {/* card */}
                  <div class={styles.card}>
                    {/* heading */}
                    <div class={styles.heading} data-auth-enter={''}>
                      {/* titleRow */}
                      <div
                        class={classes(
                          styles.titleRow,
                          backActionSlot.filled() ? styles.withBack : undefined,
                        )}
                      >
                        {backActionSlot.filled() ? (
                          <div class={styles.backAction}>{backActionSlot()}</div>
                        ) : null}
                        {/* title */}
                        <h1 class={styles.title}>{props.title}</h1>
                      </div>
                      {descriptionSlot.filled() ? (
                        <p class={styles.description}>{descriptionSlot()}</p>
                      ) : null}
                    </div>
                    {props.children}
                    {cardFooterSlot.filled() ? (
                      <div class={styles.cardFooter}>{cardFooterSlot()}</div>
                    ) : null}
                  </div>
                </Card>
              )}
              {footerSlot.filled() ? <div class={styles.footer}>{footerSlot()}</div> : null}
            </div>
          </Dynamic>
        </div>
      </main>
    )
  })
}
